local function bx(a,b)
 local r,p=0,1
 while a>0 or b>0 do if a%2~=b%2 then r=r+p end a=math.floor(a/2) b=math.floor(b/2) p=p*2 end
 return r
end
if bit32 and bit32.bxor then bx=bit32.bxor end
